import net.e175.klaus.solarpositioning.AzimuthZenithAngle;
import org.junit.Assert;
import org.junit.Test;

import java.time.ZoneOffset;
import java.time.ZonedDateTime;

public class Grena3Test {
    @Test
    public void calculateSolarPositionValidParametersTest() {
        ZonedDateTime date = ZonedDateTime.of(2000, 1, 1, 12, 0, 0, 0, ZoneOffset.UTC);
        double latitude = 45.0;
        double longitude = 90.0;
        double deltaT = 67.0;

        AzimuthZenithAngle result = Grena3.calculateSolarPosition(date, latitude, longitude, deltaT);

        Assert.assertNotNull(result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void calculateSolarPositionInvalidDateTest() {
        Grena3.calculateSolarPosition(null, 45.0, 90.0, 67.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void calculateSolarPositionInvalidLatitudeTest() {
        ZonedDateTime date = ZonedDateTime.of(2000, 1, 1, 12, 0, 0, 0, ZoneOffset.UTC);
        Grena3.calculateSolarPosition(date, -91.0, 90.0, 67.0);
    }

    @Test
    public void calculateSolarPositionWithAdditionalParametersValidTest() {
        ZonedDateTime date = ZonedDateTime.of(2000, 1, 1, 12, 0, 0, 0, ZoneOffset.UTC);
        double latitude = 45.0;
        double longitude = 90.0;
        double deltaT = 67.0;
        double pressure = 1013.25;
        double temperature = 15.0;

        AzimuthZenithAngle result = Grena3.calculateSolarPosition(date, latitude, longitude, deltaT, pressure, temperature);

        Assert.assertNotNull(result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void calculateSolarPositionWithAdditionalParametersInvalidPressureTest() {
        ZonedDateTime date = ZonedDateTime.of(2000, 1, 1, 12, 0, 0, 0, ZoneOffset.UTC);
        Grena3.calculateSolarPosition(date, 45.0, 90.0, 67.0, -1.0, 15.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void calculateSolarPositionWithAdditionalParametersInvalidTemperatureTest() {
        ZonedDateTime date = ZonedDateTime.of(2000, 1, 1, 12, 0, 0, 0, ZoneOffset.UTC);
        Grena3.calculateSolarPosition(date, 45.0, 90.0, 67.0, 1013.25, -274.0);
    }
}
